package com.hbm.entity.mob.ufo;
import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.network.codec.StreamCodec;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.minecraft.resources.ResourceLocation;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.level.Level;import net.neoforged.neoforge.network.PacketDistributor;import net.neoforged.neoforge.network.event.RegisterPayloadHandlersEvent;
/** Source AuxParticlePacketNT(type=ufo) sends one real ParticleMukeCloud per packet within150blocks. */
public record UfoGroundCloud(double x,double y,double z)implements CustomPacketPayload{
 public static final Type<UfoGroundCloud> TYPE=new Type<>(ResourceLocation.parse("hbm:ufo_ground_cloud"));public static final StreamCodec<RegistryFriendlyByteBuf,UfoGroundCloud> CODEC=StreamCodec.of((b,p)->{b.writeDouble(p.x);b.writeDouble(p.y);b.writeDouble(p.z);},b->new UfoGroundCloud(b.readDouble(),b.readDouble(),b.readDouble()));@Override public Type<UfoGroundCloud> type(){return TYPE;}public static void register(RegisterPayloadHandlersEvent e){e.registrar("1").playToClient(TYPE,CODEC,(packet,context)->context.enqueueWork(()->com.hbm.client.entity.ufo.UfoClient.groundCloud(packet)));}public static void send(Level level,double x,double y,double z){if(level instanceof ServerLevel server){var packet=new UfoGroundCloud(x,y,z);try(var dispatchScope=com.hbm.network.dispatch.PacketDispatch.beginPayloadGroup(server.getServer(),packet)){for(var player:server.players())if(player.distanceToSqr(x,y,z)<=22500)PacketDistributor.sendToPlayer(player,packet);dispatchScope.commit();}}}
}
